const items = $input.all();
if (!items || items.length === 0) return [{ json: { noLeads: true, total: 0 } }];

const leads = items.map(item => {
  const props = item.json.properties || {};
  const getTitle = (p) => (!p || !p.title || !p.title.length) ? '' : p.title.map(t => t.plain_text).join('');
  const getSelect = (p) => (!p || !p.select) ? '' : p.select.name || '';
  const websiteUrl = getTitle(props['Website URL']);
  let domain = '';
  try {
    const url = websiteUrl.startsWith('http') ? websiteUrl : 'https://' + websiteUrl;
    domain = new URL(url).hostname.replace('www.', '');
  } catch(e) {
    domain = websiteUrl.replace(/https?:\/\/(www\.)?/, '').split('/')[0];
  }
  return { pageId: item.json.id, website_url: websiteUrl, domain: domain.replace(/\/$/, ''), icp: getSelect(props['ICP']) };
}).filter(l => l.domain);

if (!leads.length) return [{ json: { noLeads: true, total: 0 } }];
return [{ json: { noLeads: false, leads, total: leads.length } }];

const emailsResult = $('Get Domain Emails').first().json;
const prospectsResult = $('Get Prospects').first().json;
const domainInfo = $('Get Domain Info').first().json;
const leadData = $('Loop One by One').first().json;

const pageId = leadData.pageId;
const websiteUrl = leadData.website_url;
const domain = leadData.domain;

// ── Domain info summary ──
const companyName = domainInfo?.data?.company_name || '';
const industry = domainInfo?.data?.industry || '';
const size = domainInfo?.data?.size || '';
const emailsCount = domainInfo?.meta?.emails_count || 0;
const prospectsCount = domainInfo?.meta?.prospects_count || 0;
const domainInfoLine = `Get Domain Info: Company=${companyName || 'N/A'} | Industry=${industry || 'N/A'} | Size=${size || 'N/A'} | Emails=${emailsCount} | Prospects=${prospectsCount}`;

// ── Raw data ──
const emails = emailsResult?.data || [];
const prospects = prospectsResult?.data || [];

// ── Log emails list ──
const emailsList = emails.slice(0, 15).map(e => e.email).join(', ');
const emailsLogLine = `Get Domain Emails: ${emails.length} total — ${emailsList}${emails.length > 15 ? '...' : ''}`;

// ── Log prospects list ──
const prospectsList = prospects.slice(0, 5).map(p => `${p.first_name} ${p.last_name} (${p.position || 'N/A'})`).join(', ');
const prospectsLogLine = `Get Prospects: ${prospects.length} total — ${prospectsList}${prospects.length > 5 ? '...' : ''}`;

// ── No data at all ──
if (!emails.length && !prospects.length) {
  const log = `Domain: ${domain}\n${domainInfoLine}\n${emailsLogLine}\n${prospectsLogLine}\nResult: Domain not found in Snov.io database`;
  return [{ json: {
    pageId,
    website_url: websiteUrl,
    best_email: null,
    best_name: '',
    best_position: '',
    other_contacts: '',
    snovio_log: log,
    agent_note: 'Domain not found in Snov.io database',
    email_found: false,
    company_name: companyName,
    company_industry: industry,
    company_size: size
  } }];
}

// ── Title scoring (EDIT: tune this scoring for your own ICP) ──
const seniorTitles = [
  'webmaster','web manager','web administrator',
  'it manager','it director','systems administrator','sysadmin',
  'digital manager','digital coordinator',
  'administrator','office administrator','office manager',
  'registrar','enrollment','communications manager',
  'operations manager','coordinator','content manager',
  'marketing manager','marketing coordinator',
  'director','managing director','executive director',
  'manager'
];
const midTitles = [
  'ceo','chief executive','founder','co-founder','cofounder',
  'owner','president','principal','chancellor','vice-chancellor',
  'vp','vice president','head of','chief','md','officer','controller'
];

function scoreTitle(position) {
  const pos = (position || '').toLowerCase();
  for (let i = 0; i < seniorTitles.length; i++) if (pos.includes(seniorTitles[i])) return 100 - i;
  for (let i = 0; i < midTitles.length; i++) if (pos.includes(midTitles[i])) return 50 - i;
  return 1;
}

// ── Username score fallback (EDIT: tune this scoring for your own ICP) ──
function scoreUsername(username) {
  const u = username.toLowerCase();
  const roleScores = [
    ['webmaster',95],['webadmin',93],['web',88],
    ['it',85],['sysadmin',83],['systems',80],
    ['digital',78],['admin',75],['administrator',75],
    ['registrar',72],['enrollment',70],['office',68],
    ['communications',65],['coordinator',63],['operations',60],
    ['info',55],['contact',50],['enquiries',48],['hello',45],
    ['marketing',42],['manager',40],
    ['support',20],['library',10],['forms',8],['graduation',5],
    ['ceo',15],['president',15],['director',20],['founder',12],
    ['principal',18],['chancellor',18]
  ];
  for (const [role, score] of roleScores) {
    if (u === role || u.startsWith(role + '.') || u.startsWith(role + '_')) return score;
  }
  return 25;
}

// ── Cross-reference emails with prospects ──
const matchedContacts = [];
const unmatchedEmails = [];

for (const emailObj of emails) {
  const email = emailObj.email || '';
  if (!email) continue;
  const username = email.split('@')[0].toLowerCase();

  let matched = null;
  let bestMatchScore = 0;

  for (const p of prospects) {
    const firstName = (p.first_name || '').toLowerCase().replace(/[^a-z]/g, '');
    const lastName = (p.last_name || '').toLowerCase().replace(/[^a-z]/g, '');
    const firstInitial = firstName.charAt(0);

    const patterns = [
      firstInitial + lastName,
      firstName + lastName,
      firstName + '.' + lastName,
      firstName + '_' + lastName,
      lastName + firstInitial,
      lastName + '.' + firstName,
      firstName,
      lastName,
      firstInitial + '.' + lastName,
    ];

    if (patterns.includes(username)) {
      const score = scoreTitle(p.position);
      if (score > bestMatchScore) {
        bestMatchScore = score;
        matched = p;
      }
    }
  }

  if (matched) {
    matchedContacts.push({
      email,
      firstName: matched.first_name || '',
      lastName: matched.last_name || '',
      position: matched.position || '',
      score: scoreTitle(matched.position)
    });
  } else {
    unmatchedEmails.push({ email, score: scoreUsername(username) });
  }
}

// ── Sort by score ──
matchedContacts.sort((a, b) => b.score - a.score);
unmatchedEmails.sort((a, b) => b.score - a.score);

// ── Build cross-reference log ──
const matchLog = matchedContacts.slice(0, 8).map(c => `  ${c.firstName} ${c.lastName} (${c.position}) → ${c.email} ✅`).join('\n');
const noMatchNote = matchedContacts.length === 0 ? '  No matches found — using email scoring fallback' : '';
const crossRefLine = `Cross-Reference Matches (${matchedContacts.length} of ${emails.length} emails matched):\n${matchLog || noMatchNote}`;

// ── Pick best contact ──
let bestContact = null;
let otherContacts = [];

if (matchedContacts.length > 0) {
  bestContact = matchedContacts[0];
  otherContacts = [
    ...matchedContacts.slice(1).map(c => `${c.firstName} ${c.lastName} (${c.position}) - ${c.email}`),
    ...unmatchedEmails.slice(0, 5).map(e => e.email)
  ];
} else if (unmatchedEmails.length > 0) {
  const best = unmatchedEmails[0];
  bestContact = { email: best.email, firstName: best.email.split('@')[0], lastName: '', position: 'Unknown' };
  otherContacts = unmatchedEmails.slice(1, 10).map(e => e.email);
}

if (!bestContact) {
  const log = `Domain: ${domain}\n${domainInfoLine}\n${emailsLogLine}\n${prospectsLogLine}\n${crossRefLine}\nResult: No valid contacts found`;
  return [{ json: {
    pageId,
    website_url: websiteUrl,
    best_email: null,
    best_name: '',
    best_position: '',
    other_contacts: '',
    snovio_log: log,
    agent_note: 'No valid contacts found',
    email_found: false,
    company_name: companyName,
    company_industry: industry,
    company_size: size
  } }];
}

const bestEmail = bestContact.email;
const bestName = [bestContact.firstName, bestContact.lastName].filter(Boolean).join(' ');
const bestPosition = bestContact.position || '';
const resultLine = `Result: Best contact — ${bestName}${bestPosition ? ' (' + bestPosition + ')' : ''} — ${bestEmail}`;

const fullLog = `Domain: ${domain}\n${domainInfoLine}\n${emailsLogLine}\n${prospectsLogLine}\n${crossRefLine}\n${resultLine}`;

return [{ json: {
  pageId,
  website_url: websiteUrl,
  best_email: bestEmail,
  best_name: bestName,
  best_position: bestPosition,
  other_contacts: otherContacts.slice(0, 10).join(', '),
  snovio_log: fullLog,
  agent_note: '',
  email_found: true,
  company_name: companyName,
  company_industry: industry,
  company_size: size
} }];

